// Нууц үгтэй ажиллах туслахууд. Энэ файлыг өөрчлөх шаардлагагүй.
//
// Жинхэнэ Web Crypto (PBKDF2-SHA256) ашиглаж байна. Нууц үгийг ЯМАР Ч
// тохиолдолд задгайгаар хадгалж болохгүй — зөвхөн давс (salt) ба хэш.
// Бодит систем дээр энэ хоёр функцийг өөрөө бичихгүй, argon2 эсвэл bcrypt
// сан ашигладаг (Хийе платформ өөрөө argon2id хэрэглэдэг).

const PBKDF2_ITERATIONS = 100000;

function toHex(buffer) {
  return Array.from(new Uint8Array(buffer))
    .map((byte) => byte.toString(16).padStart(2, "0"))
    .join("");
}

function randomSalt() {
  return toHex(crypto.getRandomValues(new Uint8Array(16)));
}

async function hashPassword(password, salt) {
  const key = await crypto.subtle.importKey(
    "raw",
    new TextEncoder().encode(password),
    { name: "PBKDF2" },
    false,
    ["deriveBits"],
  );

  const bits = await crypto.subtle.deriveBits(
    {
      name: "PBKDF2",
      salt: new TextEncoder().encode(salt),
      iterations: PBKDF2_ITERATIONS,
      hash: "SHA-256",
    },
    key,
    256,
  );

  return toHex(bits);
}

async function verifyPassword(password, user) {
  const attempt = await hashPassword(password, user.salt);
  return attempt === user.hash;
}

